<script setup lang="ts">
import { useAimsModule } from '../useAimsModule'
const route = useRoute(); const { moduleUrl } = useAimsModule(); const projectId = computed(() => String(route.params.id || '')); const requirementId = computed(() => String(route.params.requirementId || ''))
const item = ref<Record<string, any> | null>(null); const loading = ref(false); const error = ref('')
async function refresh() { loading.value = true; error.value = ''; try { const response = await $fetch<{ code?: number, data?: Record<string, any> }>(moduleUrl(`/api/v1/projects/${projectId.value}/requirements/${requirementId.value}`)); if (response.code !== 0 || !response.data) throw Error('需求详情暂不可用'); item.value = response.data } catch (cause) { error.value = cause instanceof Error ? cause.message : '需求详情暂不可用' } finally { loading.value = false } }
onMounted(refresh)
</script>
<template><section class="space-y-5"><div><UButton :to="moduleUrl(`/projects/${projectId}/requirements`)" variant="link" color="neutral" icon="i-lucide-arrow-left">返回项目需求</UButton><h1 class="mt-1 text-2xl font-semibold text-highlighted">{{ item?.title || '需求详情' }}</h1><p class="mt-1 text-sm text-muted">{{ item?.reqCode || '-' }}</p></div><UAlert v-if="error" color="error" title="无法读取需求" :description="error" /><USkeleton v-else-if="loading" class="h-64 w-full" /><template v-else-if="item"><UCard><dl class="grid gap-5 sm:grid-cols-2 lg:grid-cols-3"><div><dt class="text-sm text-muted">类型</dt><dd>{{ item.type || '-' }}</dd></div><div><dt class="text-sm text-muted">优先级</dt><dd>{{ item.priority || '-' }}</dd></div><div><dt class="text-sm text-muted">状态</dt><dd>{{ item.status || '-' }}</dd></div><div><dt class="text-sm text-muted">来源</dt><dd>{{ item.source || '-' }}</dd></div><div><dt class="text-sm text-muted">里程碑</dt><dd>{{ item.milestoneName || '-' }}</dd></div><div><dt class="text-sm text-muted">当前版本</dt><dd>{{ item.currentVersion || '-' }}</dd></div></dl><p v-if="item.scopeNote" class="mt-5 whitespace-pre-wrap text-sm">{{ item.scopeNote }}</p></UCard><UCard v-if="item.contents?.length"><template #header><h2 class="font-semibold">需求内容</h2></template><div v-for="content in item.contents" :key="content.id" class="mb-5"><h3 class="font-medium">{{ content.title }}</h3><p class="mt-1 whitespace-pre-wrap text-sm text-muted">{{ content.contentMd || '暂无内容' }}</p></div></UCard></template></section></template>
